from flask import Blueprint, request, jsonify
from app.controllers.task_controller import (
    get_all_tasks,
    create_task,
    update_task,
    delete_task,
    get_task_by_id
)

# Define the Blueprint for the routes
routes = Blueprint('routes', __name__)

@routes.route('/tasks', methods=['GET'])
def fetch_tasks():
    """Fetch all tasks."""
    tasks = get_all_tasks()
    return jsonify(tasks), 200

@routes.route('/tasks/<int:task_id>', methods=['GET'])
def fetch_task(task_id):
    """Fetch a specific task by ID."""
    task = get_task_by_id(task_id)
    if task:
        return jsonify(task), 200
    return jsonify({'error': 'Task not found'}), 404

@routes.route('/tasks', methods=['POST'])
def create_new_task():
    """Create a new task."""
    data = request.json
    if not data:
        return jsonify({'error': 'Invalid or missing data'}), 400
    task = create_task(data)
    return jsonify(task), 201

@routes.route('/tasks/<int:task_id>', methods=['PUT'])
def modify_task(task_id):
    """Update an existing task."""
    data = request.json
    if not data:
        return jsonify({'error': 'Invalid or missing data'}), 400
    updated_task = update_task(task_id, data)
    if updated_task:
        return jsonify(updated_task), 200
    return jsonify({'error': 'Task not found'}), 404

@routes.route('/tasks/<int:task_id>', methods=['DELETE'])
def remove_task(task_id):
    """Delete a task."""
    result = delete_task(task_id)
    if result:
        return jsonify({'message': 'Task deleted successfully'}), 200
    return jsonify({'error': 'Task not found'}), 404

from flask import Blueprint, request, jsonify
from app.models import Task, db
from datetime import datetime

task_controller = Blueprint('task_controller', __name__)

@task_controller.route('/tasks', methods=['GET'])
def get_tasks():
    tasks = Task.query.all()
    return jsonify([task.to_dict() for task in tasks])

@task_controller.route('/tasks/<int:task_id>', methods=['GET'])
def get_task(task_id):
    task = Task.query.get(task_id)
    if task:
        return jsonify(task.to_dict())
    return jsonify({'error': 'Task not found'}), 404

@task_controller.route('/tasks', methods=['POST'])
def create_task():
    data = request.json
    title = data.get('title')
    description = data.get('description')
    priority = data.get('priority', 'Normal')
    due_date = data.get('due_date')
    if due_date:
        due_date = datetime.strptime(due_date, '%Y-%m-%d')

    new_task = Task(title=title, description=description, priority=priority, due_date=due_date)
    db.session.add(new_task)
    db.session.commit()

    return jsonify(new_task.to_dict()), 201

@task_controller.route('/tasks/<int:task_id>', methods=['PUT'])
def update_task(task_id):
    task = Task.query.get(task_id)
    if not task:
        return jsonify({'error': 'Task not found'}), 404

    data = request.json
    task.title = data.get('title', task.title)
    task.description = data.get('description', task.description)
    task.priority = data.get('priority', task.priority)
    due_date = data.get('due_date', task.due_date)
    if due_date:
        task.due_date = datetime.strptime(due_date, '%Y-%m-%d')

    db.session.commit()
    return jsonify(task.to_dict())

@task_controller.route('/tasks/<int:task_id>', methods=['DELETE'])
def delete_task(task_id):
    task = Task.query.get(task_id)
    if not task:
        return jsonify({'error': 'Task not found'}), 404

    db.session.delete(task)
    db.session.commit()
    return jsonify({'message': 'Task deleted successfully'})

@task_controller.route('/tasks/notifications', methods=['GET'])
def get_notifications():
    tasks = Task.query.filter(Task.due_date <= datetime.now()).all()
    notifications = [{'task_id': task.id, 'title': task.title, 'due_date': task.due_date} for task in tasks]
    return jsonify(notifications)

